97	function fmtCurrency(amount: number | null, currency = "USD") {
98	  if (amount == null) return "—";
99	  return new Intl.NumberFormat("en-US", {
100	    style: "currency",
101	    currency,
102	    maximumFractionDigits: 0,
103	  }).format(amount);
104	}
