108	function DeadlineBadge({ deadline }: { deadline: string | null }) {
109	  if (!deadline) return <span className="text-muted-foreground text-xs">—</span>;
110	  try {
111	    const days = differenceInDays(parseISO(deadline), new Date());
112	    if (days < 0) {
113	      return (
114	        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-red-600 dark:text-red-400">
115	          <AlertTriangle className="h-3 w-3" />
116	          {Math.abs(days)}d overdue
117	        </span>
118	      );
119	    }
120	    if (days === 0) {
121	      return <Badge variant="destructive" className="text-[10px]">Due today</Badge>;
122	    }
123	    if (days <= 3) {
124	      return <Badge variant="destructive" className="text-[10px]">{days}d left</Badge>;
125	    }
126	    if (days <= 7) {
127	      return (
128	        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-amber-600 dark:text-amber-400">
129	          <Clock className="h-3 w-3" />
130	          {days}d left
131	        </span>
132	      );
133	    }
134	    return <span className="text-[11px] text-muted-foreground">{fmtDate(deadline)}</span>;
135	  } catch {
136	    return <span className="text-muted-foreground text-xs">—</span>;
137	  }
138	}
