142	function GuarantyProgress({
143	  startDate,
144	  guaranteeDays,
145	  expiresAt,
146	}: {
147	  startDate: string | null;
148	  guaranteeDays: number | null;
149	  expiresAt: string | null;
150	}) {
151	  if (!startDate || !guaranteeDays || !expiresAt) {
152	    return <span className="text-muted-foreground text-xs">—</span>;
153	  }
154	  try {
155	    const start = parseISO(startDate);
156	    const end = parseISO(expiresAt);
157	    const total = differenceInDays(end, start);
158	    const elapsed = differenceInDays(new Date(), start);
159	    const daysLeft = differenceInDays(end, new Date());
160	
161	    if (daysLeft < 0) {
162	      return <Badge variant="destructive" className="text-[10px]">Expired</Badge>;
163	    }
164	
165	    const pct = Math.min(100, Math.max(0, (elapsed / total) * 100));
166	    const color = pct > 85 ? "bg-red-500" : pct > 60 ? "bg-amber-500" : "bg-emerald-500";
167	
168	    return (
169	      <div className="space-y-1 min-w-[100px]">
170	        <div className="flex items-center justify-between gap-2">
171	          <span className="text-[10px] text-muted-foreground">{daysLeft}d left</span>
172	          <span className="text-[10px] text-muted-foreground">{Math.round(pct)}%</span>
173	        </div>
174	        <div className="h-1.5 w-full rounded-full bg-muted overflow-hidden">
175	          <div className={`h-full rounded-full transition-all ${color}`} style={{ width: `${pct}%` }} />
176	        </div>
177	      </div>
178	    );
179	  } catch {
180	    return <span className="text-muted-foreground text-xs">—</span>;
181	  }
182	}
