41	
42	  const { data, isLoading, error } = useQuery({
43	    queryKey,
44	    queryFn: async (): Promise<AgencyClient[]> => {
45	      if (!teamId) return [];
46	      try {
47	        const { data, error } = await (supabase as any)
48	          .from("agency_clients")
49	          .select("*")
50	          .eq("team_id", teamId)
51	          .order("created_at", { ascending: false });
52	        if (error) throw error;
53	        return (data ?? []) as AgencyClient[];
54	      } catch (err) { console.error("Agency hook error:", err);
55	        return [];
56	      }
57	    },
58	    enabled: !!teamId,
59	    staleTime: 30_000,
60	  });
61	
62	  const createClient = useMutation({
63	    mutationFn: async (input: Omit<CreateClientInput, "team_id">) => {
64	      if (!teamId) throw new Error("No team");
65	      const { data, error } = await (supabase as any)
66	        .from("agency_clients")
67	        .insert({ ...input, team_id: teamId })
68	        .select()
69	        .single();
70	      if (error) throw error;
71	      return data as AgencyClient;
72	    },
73	    onSuccess: () => {
74	      queryClient.invalidateQueries({ queryKey });
75	      toast.success("Client added");
76	    },
77	    onError: (err: Error) => {
78	      toast.error(`Failed to add client: ${err.message}`);
79	    },
80	  });
81	
82	  const updateClient = useMutation({
83	    mutationFn: async ({ id, ...updates }: UpdateClientInput) => {
84	      const { data, error } = await (supabase as any)
85	        .from("agency_clients")
86	        .update(updates)
87	        .eq("id", id)
88	        .select()
89	        .single();
90	      if (error) throw error;
91	      return data as AgencyClient;
92	    },
93	    onSuccess: () => {
94	      queryClient.invalidateQueries({ queryKey });
95	      toast.success("Client updated");
96	    },
97	    onError: (err: Error) => {
98	      toast.error(`Failed to update client: ${err.message}`);
99	    },
100	  });
101	
102	  const deleteClient = useMutation({
103	    mutationFn: async (id: string) => {
104	      const { error } = await (supabase as any)
105	        .from("agency_clients")
