115	      toast.error(`Failed to delete client: ${err.message}`);
116	    },
117	  });
118	
119	  return {
120	    clients: data ?? [],
121	    isLoading,
122	    error,
123	    createClient,
124	    updateClient,
125	    deleteClient,
126	  };
