30	const EmailOutreachDialog = ({
31	  open,
32	  onOpenChange,
33	  candidateName,
34	  candidateEmail,
35	  jobTitle,
36	  matchScore,
37	  resumeId,
38	  jobId,
39	}: EmailOutreachDialogProps) => {
40	  const [subject, setSubject] = useState(() => buildDefaultSubject(jobTitle));
41	  const [bodyText, setBodyText] = useState(() =>
42	    buildDefaultTemplate(candidateName, jobTitle, matchScore)
43	  );
44	  const [isSending, setIsSending] = useState(false);
45	
46	  // Reset fields when the dialog opens with fresh values
47	  const handleOpenChange = (nextOpen: boolean) => {
48	    if (nextOpen) {
49	      setSubject(buildDefaultSubject(jobTitle));
50	      setBodyText(buildDefaultTemplate(candidateName, jobTitle, matchScore));
51	    }
52	    onOpenChange(nextOpen);
53	  };
54	
55	  const bodyHtml = bodyText.replace(/\n/g, "<br>");
56	
57	  const handleSend = async () => {
58	    if (!subject.trim()) {
59	      toast.error("Please enter a subject");
60	      return;
61	    }
62	    if (!bodyText.trim()) {
63	      toast.error("Please enter a message body");
